create extension if not exists pgcrypto;
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),content text not null check(char_length(btrim(content)) between 1 and 500),category text not null check(category in ('thought','secret','rant','regret','good')),status text not null default 'published' check(status in ('pending','published','hidden','removed')),like_count integer not null default 0 check(like_count>=0),created_at timestamptz not null default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,reason text not null check(reason in ('spam','harassment','hate','sexual','threat','other')),status text not null default 'open' check(status in ('open','reviewed','dismissed')),created_at timestamptz not null default now());
create table if not exists public.post_likes(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,client_hash text not null,created_at timestamptz not null default now(),unique(post_id,client_hash));
create table if not exists public.rate_limits(client_hash text not null,action text not null,window_start timestamptz not null,attempts integer not null default 0,primary key(client_hash,action,window_start));
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create index if not exists posts_public_idx on public.posts(status,created_at desc);
create index if not exists reports_post_idx on public.reports(post_id,created_at desc);
create index if not exists reports_status_idx on public.reports(status,created_at desc);
alter table public.posts enable row level security; alter table public.reports enable row level security; alter table public.post_likes enable row level security; alter table public.rate_limits enable row level security; alter table public.admins enable row level security;
drop policy if exists public_read_posts on public.posts; create policy public_read_posts on public.posts for select to anon,authenticated using(status='published');
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()); $$;
create or replace function public.create_post(p_content text,p_category text,p_client_token text) returns public.posts language plpgsql security definer set search_path=public as $$ declare v public.posts; h text; w timestamptz; begin if p_content is null or char_length(btrim(p_content)) not between 1 and 500 then raise exception 'invalid content'; end if; if p_category not in ('thought','secret','rant','regret','good') then raise exception 'invalid category'; end if; if p_client_token is null or char_length(p_client_token)<16 then raise exception 'invalid client'; end if; h:=encode(digest(p_client_token,'sha256'),'hex'); w:=date_trunc('hour',now()); insert into rate_limits(client_hash,action,window_start,attempts) values(h,'post',w,1) on conflict(client_hash,action,window_start) do update set attempts=rate_limits.attempts+1; if (select attempts from rate_limits where client_hash=h and action='post' and window_start=w)>5 then raise exception 'rate limited'; end if; insert into posts(content,category) values(btrim(p_content),p_category) returning * into v; return v; end $$;
create or replace function public.like_post(p_post_id uuid,p_client_token text) returns void language plpgsql security definer set search_path=public as $$ declare h text; begin if not exists(select 1 from posts where id=p_post_id and status='published') then raise exception 'not found'; end if; h:=encode(digest(coalesce(p_client_token,''),'sha256'),'hex'); insert into post_likes(post_id,client_hash) values(p_post_id,h) on conflict do nothing; if found then update posts set like_count=like_count+1 where id=p_post_id; end if; end $$;
create or replace function public.report_post(p_post_id uuid,p_reason text,p_client_token text) returns void language plpgsql security definer set search_path=public as $$ declare h text; begin if p_reason not in ('spam','harassment','hate','sexual','threat','other') then raise exception 'invalid reason'; end if; if not exists(select 1 from posts where id=p_post_id and status='published') then raise exception 'not found'; end if; h:=encode(digest(coalesce(p_client_token,''),'sha256'),'hex'); if exists(select 1 from rate_limits where client_hash=h and action='report' and window_start=date_trunc('hour',now()) and attempts>=10) then raise exception 'rate limited'; end if; insert into rate_limits(client_hash,action,window_start,attempts) values(h,'report',date_trunc('hour',now()),1) on conflict(client_hash,action,window_start) do update set attempts=rate_limits.attempts+1; insert into reports(post_id,reason) values(p_post_id,p_reason); end $$;
create or replace function public.admin_posts(p_status text default 'all') returns setof public.posts language sql security definer set search_path=public as $$ select * from posts where public.is_admin() and (p_status='all' or status=p_status) order by created_at desc; $$;
create or replace function public.admin_reports() returns table(id uuid,post_id uuid,reason text,status text,created_at timestamptz,content text) language sql security definer set search_path=public as $$ select r.id,r.post_id,r.reason,r.status,r.created_at,p.content from reports r join posts p on p.id=r.post_id where public.is_admin() order by r.created_at desc; $$;
create or replace function public.admin_set_post_status(p_post_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'forbidden'; end if; if p_status not in ('pending','published','hidden','removed') then raise exception 'invalid status'; end if; update posts set status=p_status where id=p_post_id; end $$;
create or replace function public.admin_set_report_status(p_report_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'forbidden'; end if; if p_status not in ('open','reviewed','dismissed') then raise exception 'invalid status'; end if; update reports set status=p_status where id=p_report_id; end $$;
revoke all on public.posts,public.reports,public.post_likes,public.rate_limits,public.admins from anon,authenticated; grant select on public.posts to anon,authenticated; grant execute on function public.create_post(text,text,text),public.like_post(uuid,text),public.report_post(uuid,text,text) to anon,authenticated; grant execute on function public.is_admin(),public.admin_posts(text),public.admin_reports(),public.admin_set_post_status(uuid,text),public.admin_set_report_status(uuid,text) to authenticated;
